func (w *notificationWriter) WriteHeader(code int) {w.code=code}
func streamNotification(fn http.HandlerFunc,kind string) http.HandlerFunc {
 return func(w http.ResponseWriter,r *http.Request) {
  key:="user:"
  if kind=="user" {key+=r.Context().Value("user").(*User).ID} else {key="chair:"+r.Context().Value("chair").(*Chair).ID}
  w.Header().Set("Content-Type","text/event-stream")
  w.Header().Set("Cache-Control","no-cache")
  w.Header().Set("X-Accel-Buffering","no")
  flush:=w.(http.Flusher)
  var prev []byte
  timer:=time.NewTicker(time.Second);defer timer.Stop()
  for {
   changed:=watchKey(key)
   rec:=&notificationWriter{header:make(http.Header),code:200}
   fn(rec,r)
   if rec.code!=200 {slog.Error("notification failed","body",rec.String());return}
   var envelope struct {Data json.RawMessage `json:"data"`}
   if err:=json.Unmarshal(rec.Bytes(),&envelope);err!=nil {return}
   if !bytes.Equal(envelope.Data,prev) {
    if _,err:=w.Write(append(append([]byte("data: "),envelope.Data...), '"'\\n','\\n'));err"'!=nil{return};flush.Flush()
    prev=append(prev[:0],envelope.Data...)
    continue
   }
   select {case <-changed: case <-timer.C: case <-r.Context().Done():return}
  }
 }
}
