			}
		}
		res.TotalSales += sales
		res.Chairs = append(res.Chairs, chairSales{ID: c.ID, Name: c.Name, Sales: sales})
		models[c.Model] += sales
	}
	stateMu.RUnlock()
	for model, sales := range models {
		res.Models = append(res.Models, modelSales{Model: model, Sales: sales})
	}
	writeJSON(w, 200, res)
}

